class Menu{constructor(){this.header=document.querySelector(".header");this.menuLinks=document.querySelectorAll(".menu__link");this.sections=this._getSections();this.SCROLL_OFFSET=50;this._bindEvents();this._init()}_init(){this._handleScroll()}_getSections(){const sections=[];this.menuLinks.forEach(link=>{const sectionId=link.getAttribute("href");if(sectionId.startsWith("#")){const section=document.querySelector(sectionId);if(section){sections.push(section)}}});return sections}_bindEvents(){window.addEventListener("scroll",this._handleScroll.bind(this));this.menuLinks.forEach(link=>{link.addEventListener("click",this._handleLinkClick.bind(this))})}_handleScroll(){this._handleStickyHeader();this._handleActiveLink()}_handleStickyHeader(){if(window.scrollY>this.header.offsetHeight){this.header.classList.add("header--sticky")}else{this.header.classList.remove("header--sticky")}}_handleActiveLink(){let currentSection=null;this.sections.forEach(section=>{const sectionTop=section.offsetTop-this.header.offsetHeight-this.SCROLL_OFFSET;const sectionBottom=sectionTop+section.offsetHeight;if(window.scrollY>=sectionTop&&window.scrollY<sectionBottom){currentSection=section}});this.menuLinks.forEach(link=>{link.classList.remove("menu__link--active");if(currentSection&&link.getAttribute("href")===`#${currentSection.id}`){link.classList.add("menu__link--active")}})}_handleLinkClick(event){event.preventDefault();window.mobileMenuObject.remove();const targetId=event.currentTarget.getAttribute("href");const targetSection=document.querySelector(targetId);if(targetSection){const headerHeight=this.header.offsetHeight;const targetPosition=targetSection.offsetTop-headerHeight-this.SCROLL_OFFSET;window.scrollTo({top:targetPosition,behavior:"smooth"})}}}